import {renderLanding} from './landing.mjs';
import {freshState,parseState,dayKey,validProfile,makePlan,summary,coachReply,MODES,TEAMS,ROLES,FOCI} from './engine.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 10h12m-5-5 5 5-5 5',home:'m3 9 7-6 7 6v9H3zm5 9v-6h4v6',plan:'M5 3h10v15H5zm3 4h4m-4 4h4m-4 4h3',chat:'M3 3h14v11H8l-5 4z',play:'M7 4v12l10-6z',chart:'M3 3v14h15M7 13V9m4 4V5m4 8V7',settings:'M10 3v2m0 10v2M3 10h2m10 0h2M5 5l1 1m8 8 1 1M5 15l1-1m8-8 1-1M13 10a3 3 0 1 1-6 0 3 3 0 1 1 6 0',check:'m4 10 4 4 8-9',close:'m5 5 10 10M15 5 5 15',upload:'M10 14V3m-4 4 4-4 4 4M3 13v4h14v-4',book:'M10 5C7 2 3 3 3 3v14s4-1 7 1c3-2 7-1 7-1V3s-4-1-7 2zm0 0v13',sun:'M10 2v2m0 12v2M2 10h2m12 0h2M4 4l2 2m8 8 2 2M4 16l2-2m8-8 2-2M13 10a3 3 0 1 1-6 0 3 3 0 1 1 6 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const logo=`<a class="logo" href="#home"><img src="mark.svg" alt=""><span class="brand-name">FORTNITE<small>AI COACH</small></span><span style="color:var(--muted);font-size:9px;letter-spacing:0">α</span></a>`;
let state=freshState(),loadError=false,storageFailed=false,mediaUrl=null;
try{const s=localStorage.getItem('nextdrop.v1');if(s)state=parseState(s);}catch{loadError=true;}
function save(){try{localStorage.setItem('nextdrop.v1',JSON.stringify(state));return true;}catch{storageFailed=true;toast('Не удалось сохранить в браузере. Экспортируй данные в настройках.');return false;}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const labels={dashboard:'Кабинет',plan:'Мой план',coach:'Тренер',review:'Разбор момента',journal:'Журнал',settings:'Профиль и данные'};
const navs=[['dashboard','home','Кабинет'],['plan','plan','План'],['coach','chat','Тренер'],['review','play','Разбор'],['journal','chart','Журнал'],['settings','settings','Профиль']];
function go(v){location.hash=v;}
function landing(){return renderLanding(state,logo,icon);}
function pagehead(title,sub){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div><span class="badge lime"><i class="dot"></i> МОЯ ПРАКТИКА</span></div>`;}
function dashboard(){const p=state.profile,today=dayKey(),check=state.checkins[today]||{energy:3,sleep:8};const plan=makePlan(p,check),done=state.completed[today]||[];return `${pagehead(`За работу, ${esc(p.nick)}.`,`Сегодня — один конкретный шаг. ${esc(p.mode)} · ${esc(p.team)} · ${esc(p.team==='Solo'?'Все решения на тебе':p.role)}`)}<div class="grid-main"><div class="stack"><section class="card accent"><div class="card-top"><span class="badge lime">ФОКУС СЕССИИ</span><span class="muted" style="font-size:11px">${plan.reduce((n,t)=>n+t.minutes,0)} минут</span></div><h2>${esc(p.focus)}</h2><p>Разобрать решение → проверить в практике → записать наблюдение.</p><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,done.length/3*100)}%"></div></div><p class="fine">${done.length} из 3 шагов отмечено сегодня · это отметки выполнения, а не оценка скилла</p>${plan.map(t=>`<div class="task-row"><button class="check ${done.includes(t.id)?'done':''}" data-toggle="${t.id}" aria-label="${done.includes(t.id)?'Снять отметку':'Отметить'}: ${esc(t.title)}" aria-pressed="${done.includes(t.id)}">${done.includes(t.id)?icon('check'):''}</button><div><h3>${t.title}</h3><p>${t.kind}</p></div><span class="time">${t.minutes} мин</span></div>`).join('')}<a class="btn small" href="#plan" style="margin-top:18px">Открыть задания ${icon('arrow')}</a></section><section class="card"><div class="card-top"><h2>Твоя отправная точка</h2>${icon('chart')}</div><p>${esc(summary(state))}</p><a class="btn secondary small" href="#coach">Обсудить с тренером ${icon('chat')}</a></section></div><div class="stack"><section class="card"><div class="card-top"><h3>Как ты сегодня?</h3>${icon('sun')}</div><p>Подстроим объём работы под твоё состояние.</p><form id="checkin-form"><div class="field"><label for="sleep">Сон, часов (по твоей оценке)</label><input id="sleep" name="sleep" type="number" min="0" max="24" step="0.5" value="${esc(check.sleep)}" required></div><div class="field"><label for="energy">Энергия: <output id="energy-value">${esc(check.energy)}</output> из 5</label><input id="energy" name="energy" type="range" min="1" max="5" value="${esc(check.energy)}"><div class="scale-labels"><span>Нужен отдых</span><span>Готов работать</span></div></div><button class="btn secondary small" type="submit">Обновить план</button></form></section><section class="card"><h3>Ритм за последние 7 дней</h3><div class="week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const k=dayKey(d);const active=state.sessions.some(s=>s.date===k)||(state.completed[k]?.length>0);return `<div class="day ${active?'filled':''}" title="${k}${active?': есть запись':': нет записи'}">${d.toLocaleDateString('ru',{weekday:'short'})}</div>`;}).join('')}</div><p class="fine">Подсвечены дни с записью или выполненным шагом. Отдых не обнуляет прогресс.</p></section><div class="notice" style="margin:0">Сезонная база ещё не проверена. Рекомендации по текущей мете пока выключены.</div></div></div>`;}
function planPage(){const plan=makePlan(state.profile,state.checkins[dayKey()]);const done=state.completed[dayKey()]||[];return `${pagehead('Твой план на сегодня','Рабочая гипотеза на основе анкеты. Проверяй применимость в своих матчах.')}<div class="grid-main"><div>${plan.map((t,i)=>`<article class="card task-card"><div class="card-top"><span class="badge lime">0${i+1} / ${t.kind}</span><span class="muted">${t.minutes} мин</span></div><h2>${t.title}</h2><ol>${t.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="metric-note">Что записать: ${t.metric}</div><button class="btn ${done.includes(t.id)?'secondary':''} small" data-toggle="${t.id}" style="margin-top:20px">${icon('check')}${done.includes(t.id)?'Выполнено · снять отметку':'Отметить выполнение'}</button></article>`).join('')}</div><aside class="stack"><div class="card"><h3>Почему именно этот план</h3><p>Ты выбрал «${esc(state.profile.focus)}», ${state.profile.minutes} минут и ${esc(state.profile.team)}. Задания учитывают роль и сегодняшнюю энергию.</p><p class="fine">Это стартовые упражнения проекта. Их эффективность для тебя ещё нужно проверить; мета сезона и экспертная оценка записи не включены.</p><a href="#settings" class="btn secondary small">Изменить профиль</a></div><div class="card"><h3>Кастомки — с задачей</h3><p>Noble или другое лобби имеет смысл, когда его формат и правила подходят твоей задаче. Сначала определи, какое решение проверяешь. Само количество сыгранных кастомок не показывает прогресс.</p><a href="#journal" class="btn ghost">Записать результат ↗</a></div></aside></div>`;}
function coachPage(){if(!state.messages.length){state.messages.push({role:'coach',text:`${state.profile.nick}, начнём с твоей версии. Ты выбрал «${state.profile.focus}». Вспомни один недавний момент: что произошло и какое решение ты считаешь спорным?`});save();}return `${pagehead('Разговор о твоей игре','Один эпизод. Несколько точных вопросов. Следующий шаг.')}<div class="chat-layout"><section class="card chat-window" style="padding:0"><div class="messages" id="messages" role="log" aria-label="Диалог с тренером">${state.messages.map(m=>`<div class="message ${m.role}">${m.role==='coach'?'<small>FORTNITE AI COACH · БАЗОВЫЙ ДИАЛОГ</small>':''}${esc(m.text)}</div>`).join('')}</div><form class="chat-input" id="chat-form"><label class="hidden" for="chat-message">Сообщение тренеру</label><textarea id="chat-message" name="message" rows="2" maxlength="2000" placeholder="Что произошло в твоём матче?" required></textarea><button class="btn" type="submit" aria-label="Отправить сообщение">${icon('arrow')}</button></form></section><aside class="stack chat-context"><section class="card"><h3>Контекст игрока</h3><div class="tagrow"><span class="badge">${esc(state.profile.mode)}</span><span class="badge">${esc(state.profile.team)}</span><span class="badge">${esc(state.profile.build)}</span></div><p>${esc(state.profile.team==='Solo'?'В Solo все решения принимаешь ты.':`Твоя роль: ${state.profile.role}.`)}</p><p class="fine">Базовый диалог работает по правилам. Языковая модель и анализ вложений пока не подключены.</p></section><section class="card"><h3>С чего начать</h3>${['Проиграл контест за локу','Как выполнить мой план?','Сегодня устал','Хочу разобрать клип'].map(t=>`<button class="prompt" data-prompt="${t}">${t} ↗</button>`).join('')}</section></aside></div><p class="fine" style="margin-top:14px">Первая версия: сообщения сохраняются в этом браузере. Бот не просматривает видео и не определяет причины поражения по одному результату.</p>`;}
function reviewPage(){return `${pagehead('Разбор момента','Один эпизод вместо полного турнира. Начни со своей версии.')}<div class="grid-main"><section class="card"><h2>Что будем разбирать?</h2><p>Выбери клип с войсами или скрин. Файл остаётся на устройстве; здесь пока доступен просмотр, без AI-анализа.</p><div class="upload">${icon('upload')}<strong style="font-size:13px">Короткий эпизод с контекстом</strong><p class="fine">Видео, изображение или .replay · до 100 МБ</p><input type="file" id="attachment" accept="video/mp4,video/webm,image/png,image/jpeg,image/webp,.replay" aria-label="Выбрать файл для разбора"></div><div id="file-preview"></div><form id="review-form" style="margin-top:25px"><div class="field"><label for="stage">Этап игры</label><select id="stage" name="stage">${['Контест за локу','Early game','Mid game','Late game'].map(x=>`<option ${state.review?.stage===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="review-note">Таймкод, ситуация и твоя версия</label><textarea id="review-note" name="note" maxlength="3000" required placeholder="00:42 — решил принять файт. Видел одного соперника, тиммейт был позади. Считаю, что вошёл слишком рано…">${esc(state.review?.note||'')}</textarea></div><button class="btn small" type="submit">Сохранить описание ${icon('check')}</button></form></section><aside class="stack"><section class="card"><h3>Что поможет разбору</h3><div class="listline"><span>01</span> Фрагмент до решения и сразу после него.</div><div class="listline"><span>02</span> HUD: здоровье, ресы, инвентарь и карта.</div><div class="listline"><span>03</span> Войсы команды, если участники согласны на передачу записи.</div><div class="listline"><span>04</span> Что ты знал тогда, а что узнал после матча.</div><div class="listline"><span>05</span> Твоя версия причины и один вопрос.</div></section><div class="notice" style="margin:0">Файл .replay не является видео. Парсер и сравнение с записями про-игроков ещё не подключены. Файл не сохраняется после закрытия страницы; текстовое описание сохраняется.</div></aside></div>`;}
function journalPage(){const games=state.sessions.reduce((n,x)=>n+x.matches,0),early=state.sessions.reduce((n,x)=>n+x.early,0);return `${pagehead('Журнал практики','Записывай наблюдения. Так появляется основа для следующего решения.')}<div class="metrics"><div class="metric"><strong>${state.sessions.length}</strong><span>Записей в журнале</span></div><div class="metric"><strong>${games}</strong><span>Матчей по твоим данным</span></div><div class="metric"><strong>${games?Math.round(early/games*100)+'%':'—'}</strong><span>Матчи, завершённые в early</span></div></div><div class="grid-main"><section class="card"><h2>Последние сессии</h2>${state.sessions.length?state.sessions.map((s,i)=>`<article class="session"><div class="session-top"><h3>${esc(s.date)} · ${esc(s.type)}</h3><button data-delete-session="${i}" aria-label="Удалить запись от ${esc(s.date)}">Удалить</button></div><div class="tagrow"><span class="badge">${s.matches} матчей</span><span class="badge">${s.early} в early</span></div><p>${esc(s.note)}</p></article>`).join(''):`<div class="empty">${icon('book')}<h3>Начни с сегодняшней практики</h3><p>Запиши одну ситуацию и своё решение. Здесь появится история твоей работы.</p></div>`}</section><section class="card"><h3>Добавить сессию</h3><form id="session-form"><div class="field"><label for="session-date">Дата</label><input id="session-date" name="date" type="date" value="${dayKey()}" max="${dayKey()}" required></div><div class="field"><label for="session-type">Тип практики</label><select id="session-type" name="type"><option>Турнир</option><option>Кастомки</option><option>Ranked</option><option>Тренировка</option><option>Разбор записи</option></select></div><div class="form-grid"><div class="field"><label for="matches">Матчей</label><input id="matches" name="matches" type="number" min="0" max="100" required></div><div class="field"><label for="early">Завершились в early</label><input id="early" name="early" type="number" min="0" max="100" required></div></div><div class="field"><label for="session-note">Что проверял, что увидел, что дальше?</label><textarea id="session-note" name="note" maxlength="3000" required></textarea></div><p class="error" id="session-error" role="alert"></p><button class="btn small" type="submit">Сохранить сессию</button></form></section></div>`;}
function settingsPage(){const p=state.profile;return `${pagehead('Твой профиль','Данные, на которых строится первая версия плана.')}<div class="grid-main"><div class="stack"><section class="card"><div class="card-top"><h2>${esc(p.nick)}</h2><button class="btn secondary small" data-action="edit-profile">Изменить</button></div><div class="tagrow">${[p.mode,p.team,p.build,p.team==='Solo'?'Все роли':p.role,`${p.minutes} мин`].map(t=>`<span class="badge">${esc(t)}</span>`).join('')}</div><p>Фокус: ${esc(p.focus)}.</p></section><section class="card"><h3>Турнирные показатели</h3><p>Введённые тобой значения. Автоматическая проверка пока не подключена. Пустое поле означает «нет данных».</p><form id="stats-form"><div class="form-grid">${[['pr','Power Ranking'],['earnings','Призовые, USD'],['events','Турнирных сессий']].map(([k,l])=>`<div class="field"><label for="stat-${k}">${l}</label><input id="stat-${k}" name="${k}" type="number" min="0" max="1000000000" step="${k==='earnings'?'0.01':'1'}" value="${state.stats[k]??''}"></div>`).join('')}</div><button class="btn secondary small" type="submit">Сохранить показатели</button></form></section><section class="card"><h3>Ссылки на твои профили</h3><p>Сохраняются как ссылки для проверки. Страницы не скачиваются автоматически.</p><form id="links-form"><div class="field"><label for="tracker">Fortnite Tracker</label><input id="tracker" name="tracker" type="url" value="${esc(p.tracker||'')}" placeholder="https://fortnitetracker.com/fortnite/profile/…"></div><div class="field"><label for="osirion">Osirion</label><input id="osirion" name="osirion" type="url" value="${esc(p.osirion||'')}" placeholder="https://osirion.gg/…"></div><p id="links-error" class="error" role="alert"></p><button class="btn secondary small" type="submit">Сохранить ссылки</button></form>${[['tracker','Открыть Fortnite Tracker'],['osirion','Открыть Osirion']].filter(([k])=>safeProfileURL(p[k],k)).map(([k,t])=>`<a class="source-link" href="${esc(p[k])}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</section></div><aside class="stack"><section class="card"><h3>Сохранение и перенос</h3><p>Профиль, журнал и диалог хранятся только в этом браузере. Сделай резервную копию для переноса на другой девайс.</p><button class="btn secondary small" data-action="export">Экспортировать JSON</button><div class="field" style="margin-top:22px"><label for="import">Импортировать резервную копию</label><input type="file" id="import" accept="application/json,.json"></div><p class="fine">Импорт заменит текущий профиль после подтверждения. Медиафайлы в копию не входят.</p></section><section class="card"><h3>Состояние базы</h3><span class="badge amber">Требует проверки</span><p style="margin-top:15px">Мета сезона и автоматический монитор обновлений ещё не подключены. Сезонные советы отключены.</p><a class="source-link" href="https://www.fortnite.com/news" target="_blank" rel="noopener noreferrer">Официальные обновления ↗</a><a class="source-link" href="https://www.fortnite.com/competitive" target="_blank" rel="noopener noreferrer">Fortnite Competitive ↗</a></section><section class="card"><h3>Удаление данных</h3><p>Удалит профиль, диалог и журнал из этого браузера.</p><button class="btn danger small" data-action="reset">Удалить мои данные</button></section></aside></div>`;}
function safeProfileURL(value,type){if(!value)return false;try{const u=new URL(value);return u.protocol==='https:'&&[type==='tracker'?'fortnitetracker.com':'osirion.gg',type==='tracker'?'www.fortnitetracker.com':'www.osirion.gg'].includes(u.hostname)&&!u.username&&!u.password;}catch{return false;}}
function render(){let route=location.hash.slice(1)||'home';const home=['home','how','principles','faq'].includes(route);if(!home&&!state.profile){location.hash='home';return;}if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(home){$('#app').innerHTML=landing();if(route!=='home')requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView());}else{if(!labels[route])route='dashboard';const pages={dashboard,plan:planPage,coach:coachPage,review:reviewPage,journal:journalPage,settings:settingsPage};$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${logo}<div><p class="nav-label">ТВОЯ РАБОЧАЯ ЗОНА</p><nav class="sidenav">${navs.map(([id,i,l])=>`<a href="#${id}" class="navitem ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('')}</nav></div><div class="side-bottom"><span class="badge lime">FORTNITE AI COACH · ALPHA</span><p>Твоя работа.<br>Твой следующий шаг.</p><a href="#home">О проекте ↗</a></div></aside><main class="main"><header class="appbar"><span class="crumb">Рабочая зона / ${labels[route]}</span><a href="#home" class="mobile-brand">FORTNITE AI COACH ↗</a><div class="userchip"><span>${esc(state.profile.nick)}</span><a href="#settings" class="avatar" aria-label="Открыть профиль">${esc(state.profile.nick.slice(0,1).toUpperCase())}</a></div></header>${pages[route]()}</main></div>`;if(route==='coach')requestAnimationFrame(()=>{const m=$('#messages');m.scrollTop=m.scrollHeight;});}if(storageFailed)toast('Сохранение недоступно. Сделай экспорт данных.');}
let step=0,draft={};
function onboarding(edit=false){step=0;draft=edit?{...state.profile}:{nick:'',mode:'Battle Royale',team:'Solo',build:'Build',role:'IGL',focus:'Контест за локу',minutes:40};renderOnboarding();$('#onboarding').showModal();}
const options=(key,values)=>`<div class="options">${values.map(v=>`<button type="button" class="option ${String(draft[key])===String(v)?'selected':''}" data-option="${key}" data-value="${v}" aria-pressed="${String(draft[key])===String(v)}">${typeof v==='number'?`${v} мин`:v}</button>`).join('')}</div>`;
function renderOnboarding(){const titles=['С чего начинаем?','Твоя роль в игре','На чём сосредоточимся?','План, который впишется в день'];const desc=['Никнейм нужен для профиля. Проверка Epic-аккаунта пока не выполняется.','Выбери формат, под который нужна практика. Обязанности внутри команды уточняются отдельно.','Это твоя стартовая гипотеза. После наблюдений её можно изменить.','Выбери комфортное время на одну сессию. Позже учтём сегодняшнюю энергию.'];let content='';if(step===0)content=`<div class="field"><label for="nick">Твой Epic-никнейм</label><input id="nick" maxlength="32" autocomplete="nickname" value="${esc(draft.nick)}" placeholder="Как к тебе обращаться?" required></div><div class="field-label">Режим</div>${options('mode',MODES)}<div class="field-label">Строительство</div>${options('build',['Build','Zero Build'])}`;if(step===1)content=`<div class="field-label">Состав</div>${options('team',TEAMS)}${draft.team==='Solo'?'<div class="notice">В Solo ты принимаешь решения, файтишь и отвечаешь за собственную игру. Отдельную командную роль выбирать не нужно.</div>':`<div class="field-label">Твоя основная роль</div>${options('role',draft.team==='Duo'?['IGL','Фраггер']:ROLES)}<p class="fine">Саппорт в Trio рассматривается как второй фраггер. Конкретные обязанности зависят от договорённостей команды.</p>`}`;if(step===2)content=`<div class="field-label">Что сейчас чаще вызывает вопросы?</div>${options('focus',draft.team==='Solo'?FOCI.filter(x=>x!=='Коммуникация'):FOCI)}`;if(step===3)content=`${options('minutes',[20,40,60,90])}<div class="notice">Дисциплина — выполнять осмысленный план и честно разбирать результат. Отдых тоже часть работы. Здесь нет штрафа за пропущенный день.</div><p class="fine">Первая версия сохраняет данные в этом браузере. Персональный план строится по правилам; полноценный AI-тренер ещё не подключён.</p>`;$('#onboarding').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><span>ТВОЯ ОТПРАВНАЯ ТОЧКА / ${step+1} ИЗ 4</span><button class="close" data-action="close-dialog" aria-label="Закрыть опрос">${icon('close')}</button></div><div class="steps">${[0,1,2,3].map(i=>`<span class="${i<=step?'current':''}"></span>`).join('')}</div><h2 id="onboard-title">${titles[step]}</h2><p>${desc[step]}</p>${content}<p class="error" id="onboard-error" role="alert"></p><div class="dialog-actions"><button class="btn ghost" data-action="previous-step">${step?'← Назад':'Позже'}</button><button class="btn small" data-action="next-step">${step===3?'Создать мой план':'Продолжить'} ${icon('arrow')}</button></div></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='start'){state.profile?go('dashboard'):onboarding();}if(a==='edit-profile')onboarding(true);if(a==='close-dialog')$('#onboarding').close();if(a==='previous-step'){if(!step)$('#onboarding').close();else{step--;renderOnboarding();}}if(a==='next-step'){if(step===0){draft.nick=$('#nick').value.trim();if(!draft.nick){$('#onboard-error').textContent='Укажи никнейм, чтобы продолжить.';$('#nick').focus();return;}}if(step<3){step++;renderOnboarding();}else if(validProfile(draft)){state.profile={...draft,minutes:Number(draft.minutes)};save();$('#onboarding').close();if(location.hash==='#dashboard')render();else go('dashboard');toast('Профиль готов. Начнём с одной задачи.');}}if(b.dataset.option){if($('#nick'))draft.nick=$('#nick').value;draft[b.dataset.option]=b.dataset.option==='minutes'?Number(b.dataset.value):b.dataset.value;if(draft.team==='Solo'&&draft.focus==='Коммуникация')draft.focus='Ротации';if(draft.team==='Duo'&&draft.role==='Саппорт')draft.role='Фраггер';renderOnboarding();}if(b.dataset.toggle){const key=dayKey(),id=b.dataset.toggle;const done=state.completed[key]||[];state.completed[key]=done.includes(id)?done.filter(x=>x!==id):[...done,id];save();render();}if(b.dataset.prompt){$('#chat-message').value=b.dataset.prompt;$('#chat-message').focus();}if(b.dataset.deleteSession!==undefined&&confirm('Удалить эту запись?')){state.sessions.splice(Number(b.dataset.deleteSession),1);save();render();}if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`nextdrop-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='reset'&&confirm('Удалить весь профиль, журнал и диалог из этого браузера?')){try{localStorage.removeItem('nextdrop.v1');}catch{}state=freshState();go('home');toast('Локальные данные удалены.');}});
document.addEventListener('input',e=>{if(e.target.id==='energy')$('#energy-value').textContent=e.target.value;});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='checkin-form'){state.checkins[dayKey()]={sleep:Number(d.get('sleep')),energy:Number(d.get('energy'))};save();render();toast('Объём плана обновлён.');}if(f.id==='chat-form'){const text=String(d.get('message')).trim();if(!text)return;state.messages.push({role:'user',text},{role:'coach',text:coachReply(text,state)});state.messages=state.messages.slice(-100);save();render();$('#chat-message').focus();}if(f.id==='review-form'){state.review={stage:d.get('stage'),note:String(d.get('note')).trim()};if(save())toast('Описание сохранено. Файл остаётся только в текущем просмотре.');}if(f.id==='session-form'){const matches=Number(d.get('matches')),early=Number(d.get('early'));if(!Number.isInteger(matches)||!Number.isInteger(early)||early>matches){$('#session-error').textContent='Матчи должны быть целыми числами. Early-исходов не может быть больше всех матчей.';return;}state.sessions.unshift({date:d.get('date'),type:d.get('type'),matches,early,note:String(d.get('note')).trim()});state.sessions=state.sessions.slice(0,365);save();render();toast('Запись добавлена.');}if(f.id==='stats-form'){for(const k of ['pr','earnings','events'])state.stats[k]=d.get(k)===''?null:Number(d.get(k));if(save())toast('Показатели сохранены как введённые тобой.');}if(f.id==='links-form'){for(const k of ['tracker','osirion']){const val=String(d.get(k)).trim();if(val&&!safeProfileURL(val,k)){$('#links-error').textContent=`Нужна HTTPS-ссылка на ${k==='tracker'?'fortnitetracker.com':'osirion.gg'}.`;return;}}for(const k of ['tracker','osirion'])state.profile[k]=String(d.get(k)).trim();save();render();toast('Ссылки сохранены.');}});
document.addEventListener('change',async e=>{if(e.target.id==='import'){const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('Копия слишком большая: максимум 2 МБ.');return;}try{const incoming=parseState(await file.text());if(confirm(`Заменить текущие данные профилем ${incoming.profile.nick}?`)){state=incoming;save();render();toast('Данные восстановлены.');}}catch(err){toast('Не удалось прочитать копию: '+err.message);}}if(e.target.id==='attachment'){const file=e.target.files[0];if(!file)return;const preview=$('#file-preview');preview.replaceChildren();if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(file.size>100*1024*1024){toast('Выбери отдельный фрагмент до 100 МБ.');e.target.value='';return;}const name=document.createElement('p');name.className='fine';name.textContent=`${file.name} · ${(file.size/1048576).toFixed(1)} МБ · только локальный просмотр`;preview.append(name);if(/\.(mp4|webm)$/i.test(file.name)&&file.type.startsWith('video/')){mediaUrl=URL.createObjectURL(file);const v=document.createElement('video');v.controls=true;v.src=mediaUrl;v.className='media-preview';v.preload='metadata';v.addEventListener('error',()=>toast('Браузер не смог воспроизвести этот формат.'));preview.append(v);}else if(/^image\/(png|jpeg|webp)$/.test(file.type)){mediaUrl=URL.createObjectURL(file);const img=document.createElement('img');img.src=mediaUrl;img.alt='Прикреплённый скриншот';img.className='media-preview';preview.append(img);}else{const note=document.createElement('p');note.className='notice';note.textContent=/\.replay$/i.test(file.name)?'Файл выбран, но парсер .replay ещё не подключён. Для просмотра добавь видеофрагмент.':'Этот формат не поддерживается для просмотра. Выбери MP4, WebM, PNG, JPEG или WebP.';preview.append(note);}}});
window.addEventListener('hashchange',()=>{render();if(!['#how','#principles','#faq'].includes(location.hash))window.scrollTo(0,0);});render();if(loadError)toast('Сохранение не удалось прочитать. Исходная запись не удалена.');
